import pytest


def config_value(text: str, key: str) -> str:
    """Return the value for `key` in a `name=value` per-line config text.

    Rules:
    - The text is split into lines; each line is split at its first "=".
    - Whitespace around the name and around the value is stripped.
    - Blank lines, lines whose first non-space character is "#", and lines
      without "=" are ignored.
    - Key matching is exact and case-sensitive.
    - The value is everything after the first "=" (so it may itself contain
      "="), and may be empty.
    - If the key appears more than once, the first occurrence wins.
    - If the key is absent, return "".
    - Does not read any files; `text` is the only input.
    """
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        name, sep, value = line.partition("=")
        if not sep:
            continue
        if name.strip() == key:
            return value.strip()
    return ""


def test_basic_lookup() -> None:
    assert config_value("a=1\nb=2\nc=3", "b") == "2"


def test_missing_key_returns_empty() -> None:
    assert config_value("a=1\nb=2", "z") == ""


def test_empty_text() -> None:
    assert config_value("", "a") == ""


def test_whitespace_stripped_around_name_and_value() -> None:
    assert config_value("  name  =   hello world  \n", "name") == "hello world"


def test_value_may_contain_equals() -> None:
    assert config_value("url=http://x/?a=b&c=d", "url") == "http://x/?a=b&c=d"


def test_empty_value_present_key() -> None:
    assert config_value("a=\nb=2", "a") == ""


def test_comments_ignored() -> None:
    text = "# a=1\n   # a=2\na=3"
    assert config_value(text, "a") == "3"


def test_commented_out_key_is_absent() -> None:
    assert config_value("# a=1", "a") == ""


def test_blank_and_malformed_lines_ignored() -> None:
    text = "\n   \nnoequals\na=1\n"
    assert config_value(text, "a") == "1"
    assert config_value(text, "noequals") == ""


def test_first_occurrence_wins() -> None:
    assert config_value("a=1\na=2", "a") == "1"


def test_case_sensitive() -> None:
    assert config_value("Key=1", "key") == ""
    assert config_value("Key=1", "Key") == "1"


def test_key_must_match_exactly_not_prefix() -> None:
    assert config_value("abc=1", "ab") == ""
    assert config_value("ab=1\nabc=2", "abc") == "2"


def test_value_is_not_matched_as_key() -> None:
    assert config_value("a=b\nb=", "b") == ""
    assert config_value("a=b", "b") == ""


def test_crlf_line_endings() -> None:
    assert config_value("a=1\r\nb=2\r\n", "b") == "2"


@pytest.mark.parametrize(
    ("text", "key", "expected"),
    [
        ("x=1", "x", "1"),
        ("x = 1", "x", "1"),
        ("\tx\t=\t1\t", "x", "1"),
        ("y=2\nx=1", "x", "1"),
        ("y=2", "x", ""),
    ],
)
def test_parametrized(text: str, key: str, expected: str) -> None:
    assert config_value(text, key) == expected

